# Fetch all downloaded songs (paginate)
all_downloaded = []
page_index = 0
while True:
    page = apis.spotify.show_downloaded_songs(access_token=access_token, page_index=page_index, page_limit=20)
    if not page:
        break
    all_downloaded.extend(page)
    if len(page) < 20:
        break
    page_index += 1
print(f"Total downloaded songs: {len(all_downloaded)}")
# Build a map from song_id to duration and album_id
song_duration = {s['song_id']: s['duration'] for s in all_downloaded}
song_album = {s['song_id']: s['album_id'] for s in all_downloaded}
print("Sample:", all_downloaded[0] if all_downloaded else "None")

